func TestNewerStable(t *testing.T) {
	tests := []struct {
		current, candidate string
		want               bool
	}{
		{"v1.0.0", "v1.1.0", true},
		{"1.1.0", "1.1.0", false},
		{"1.2.0", "1.1.0", false},
		{"1.1.0-rc.1", "1.1.0", true},
		{"1.1.0-rc.1", "1.1.0-rc.2", false},
		{"1.1.0+build", "1.1.0", false},
		{"dev", "1.1.0", false},
		{"", "1.1.0", false},
		{"1.0.0", "invalid", false},
	}
	for _, tt := range tests {
		t.Run(tt.current+"_"+tt.candidate, func(t *testing.T) {
			if got := newerStable(tt.current, tt.candidate); got != tt.want {
				t.Fatalf("newerStable(%q, %q) = %v, want %v", tt.current, tt.candidate, got, tt.want)
			}
		})
	}
}

